BEGIN;
CREATE TABLE "DevelopmentDeployment"(
 id TEXT PRIMARY KEY,"storyId" TEXT NOT NULL REFERENCES "Item"(id) ON DELETE RESTRICT,"executionId" TEXT NOT NULL REFERENCES "StoryExecution"(id) ON DELETE RESTRICT,"buildId" TEXT NOT NULL REFERENCES "DevelopmentBuild"(id) ON DELETE RESTRICT,"systemId" TEXT NOT NULL REFERENCES "Item"(id) ON DELETE RESTRICT,"repositoryId" TEXT NOT NULL REFERENCES "Repository"(id) ON DELETE RESTRICT,"repositoryVersion" INTEGER NOT NULL,"projectId" INTEGER NOT NULL,"environmentId" TEXT NOT NULL REFERENCES "Environment"(id) ON DELETE RESTRICT,"targetId" TEXT REFERENCES "EnvironmentTarget"(id) ON DELETE RESTRICT,"preparationId" TEXT REFERENCES "EnvironmentOperation"(id) ON DELETE RESTRICT,"expectedDeploymentId" TEXT REFERENCES "DevelopmentDeployment"(id) ON DELETE RESTRICT,
 number INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','paused','blocked','failed','unknown','succeeded','cancelled')),message TEXT NOT NULL DEFAULT '',"actorId" TEXT NOT NULL,"actorName" TEXT NOT NULL,reason TEXT NOT NULL,"sourceSha" TEXT NOT NULL,"contractDigest" TEXT NOT NULL,"unitId" TEXT NOT NULL,profile TEXT NOT NULL CHECK(profile='node24-http-v1'),"configDigest" TEXT NOT NULL,"imageId" TEXT NOT NULL,"archiveDigest" TEXT NOT NULL,"artifactSize" INTEGER NOT NULL CHECK("artifactSize">0 AND "artifactSize"<=536870912),
 "leaseId" TEXT,"leaseUntil" TIMESTAMP(3),"dispatchStartedAt" TIMESTAMP(3),"startedAt" TIMESTAMP(3),"finishedAt" TIMESTAMP(3),proof JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE("storyId",number),CHECK(state<>'succeeded' OR ("targetId" IS NOT NULL AND "dispatchStartedAt" IS NOT NULL AND "finishedAt" IS NOT NULL AND proof IS NOT NULL AND jsonb_typeof(proof)='object' AND coalesce(proof->>'imageId'="imageId",false) AND coalesce(proof->>'archiveDigest'="archiveDigest",false) AND coalesce(proof->>'sourceSha'="sourceSha",false) AND coalesce(proof->>'containerId' ~ '^[a-f0-9]{64}$',false) AND coalesce(proof->>'url' ~ '^http://localhost:[0-9]{4,5}$',false) AND coalesce(length(proof->>'healthAt')>10,false)))
);
CREATE INDEX "DevelopmentDeployment_state_createdAt_idx" ON "DevelopmentDeployment"(state,"createdAt");CREATE INDEX "DevelopmentDeployment_environmentId_createdAt_idx" ON "DevelopmentDeployment"("environmentId","createdAt");
CREATE UNIQUE INDEX "DevelopmentDeployment_one_pending_environment" ON "DevelopmentDeployment"("environmentId") WHERE state IN ('queued','running','paused','unknown');
CREATE FUNCTION validate_development_deployment() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE build "DevelopmentBuild";env "Environment";repo "Repository";target "EnvironmentTarget";preparation "EnvironmentOperation";
BEGIN
 IF TG_OP='INSERT' THEN
  SELECT * INTO build FROM "DevelopmentBuild" WHERE id=NEW."buildId";SELECT * INTO repo FROM "Repository" WHERE id=NEW."repositoryId";SELECT * INTO env FROM "Environment" WHERE id=NEW."environmentId";
  IF build.id IS NULL OR build.state<>'succeeded' OR build."storyId"<>NEW."storyId" OR build."executionId"<>NEW."executionId" OR build."systemId"<>NEW."systemId" OR build."repositoryId"<>repo.id OR build."projectId"<>NEW."projectId" OR repo.version<>NEW."repositoryVersion" OR env.code<>'DEV' OR env."repositoryId"<>repo.id OR NEW."sourceSha"<>build."sourceSha" OR NEW."contractDigest"<>build."contractDigest" OR NEW."unitId"<>build."unitId" OR NEW."imageId" IS DISTINCT FROM build."imageId" OR NEW."archiveDigest" IS DISTINCT FROM build."archiveDigest" OR NEW."artifactSize" IS DISTINCT FROM build."artifactSize" OR NEW.number<>coalesce((SELECT max(number)+1 FROM "DevelopmentDeployment" WHERE "storyId"=NEW."storyId"),1) THEN RAISE EXCEPTION 'Exact confirmed build and DEV environment required'; END IF;
  IF NEW."expectedDeploymentId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "DevelopmentDeployment" prior WHERE prior.id=NEW."expectedDeploymentId" AND prior."environmentId"=NEW."environmentId" AND prior.state='succeeded') THEN RAISE EXCEPTION 'Exact previous deployment required';END IF;
  IF NEW."targetId" IS NULL THEN
   SELECT * INTO preparation FROM "EnvironmentOperation" WHERE id=NEW."preparationId";
   IF preparation.id IS NULL OR preparation."environmentId"<>env.id OR preparation."configDigest"<>NEW."configDigest" THEN RAISE EXCEPTION 'Explicit target preparation required'; END IF;
  END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','version','message','targetId','leaseId','leaseUntil','dispatchStartedAt','startedAt','finishedAt','proof','updatedAt']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','version','message','targetId','leaseId','leaseUntil','dispatchStartedAt','startedAt','finishedAt','proof','updatedAt']) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Preserve deployment intent and version'; END IF;
  IF OLD."targetId" IS NOT NULL AND NEW."targetId" IS DISTINCT FROM OLD."targetId" OR OLD."dispatchStartedAt" IS NOT NULL AND NEW."dispatchStartedAt" IS DISTINCT FROM OLD."dispatchStartedAt" OR OLD.proof IS NOT NULL AND NEW.proof IS DISTINCT FROM OLD.proof OR OLD.state='succeeded' AND NEW.state<>'succeeded' THEN RAISE EXCEPTION 'Preserve known deployment effects'; END IF;
 END IF;
 IF NEW."targetId" IS NOT NULL THEN SELECT * INTO target FROM "EnvironmentTarget" WHERE id=NEW."targetId";IF target.id IS NULL OR target."environmentId"<>NEW."environmentId" OR target."systemId"<>NEW."systemId" OR target."configDigest"<>NEW."configDigest" OR target."unitId"<>NEW."unitId" THEN RAISE EXCEPTION 'Exact confirmed target required'; END IF;END IF;
 RETURN NEW;
END; $$;
CREATE TRIGGER development_deployment_validate BEFORE INSERT OR UPDATE ON "DevelopmentDeployment" FOR EACH ROW EXECUTE FUNCTION validate_development_deployment();CREATE TRIGGER development_deployment_no_delete BEFORE DELETE ON "DevelopmentDeployment" FOR EACH ROW EXECUTE FUNCTION prevent_history_mutation();CREATE TRIGGER development_deployment_no_truncate BEFORE TRUNCATE ON "DevelopmentDeployment" FOR EACH STATEMENT EXECUTE FUNCTION prevent_history_mutation();
GRANT SELECT,INSERT,UPDATE ON "DevelopmentDeployment" TO sdlc_portal_app;GRANT UPDATE ON "Environment" TO sdlc_portal_app;
COMMIT;
